#!/usr/bin/env node
import { readFileSync } from 'node:fs';
import { lint } from '../src/index.js';

const file = process.argv[2];
if (file === undefined) {
  process.stderr.write('usage: jsonl-lint <file>\n');
  process.exit(2);
}

let text;
try {
  text = readFileSync(file, 'utf8');
} catch (err) {
  process.stderr.write(`jsonl-lint: cannot read ${file}: ${err.message}\n`);
  process.exit(2);
}

const problems = lint(text);
for (const { line, error } of problems) {
  process.stdout.write(`${file}:${line}: ${error.replace(/\r?\n/g, ' ')}\n`);
}
process.exit(problems.length > 0 ? 1 : 0);
/**
 * Check every row of JSONL text.
 * Lines are 1-based and split on \n (a trailing \r is tolerated). Blank or
 * whitespace-only lines are skipped but still counted. A last line without a
 * trailing newline is checked like any other.
 * @param {string} text
 * @returns {{ line: number, error: string }[]}
 */
export function lint(text) {
  const problems = [];
  const lines = String(text).split('\n');
  for (let i = 0; i < lines.length; i++) {
    const row = lines[i].endsWith('\r') ? lines[i].slice(0, -1) : lines[i];
    if (row.trim() === '') continue;
    try {
      JSON.parse(row);
    } catch (err) {
      problems.push({ line: i + 1, error: err.message });
    }
  }
  return problems;
}
